MODULES = []
for row in MODULE_ROWS:
    (mid, title, intro, definition, why, real_life, prerequisites, explanation, concepts,
     syntax, examples, interview, exercises) = row
    MODULES.append({
        'id': mid, 'title': title, 'intro': intro, 'definition': definition,
        'why': why, 'real_life': real_life, 'prerequisites': prerequisites,
        'explanation': explanation, 'concepts': concepts, 'syntax': syntax,
        'examples': [{'title': t, 'code': c, 'explanation': e} for t,c,e in examples],
        'interview': interview, 'exercises': exercises,
        'mistakes': [
            f"Using a feature from {title.lower()} without checking its input assumptions.",
            "Copying code without tracing the value of each important variable.",
            "Testing only the happy path and ignoring empty, invalid or boundary input.",
            "Using unclear names or combining too many responsibilities in one block.",
        ],
        'tips': [
            "Run each example yourself and change one value at a time.",
            "Predict the output before running the code, then explain any difference.",
            "Keep a small notebook of errors, fixes and concepts you want to revisit.",
            "Prefer readable, tested code over clever code that is hard to maintain.",
        ],
        'summary': f"You learned the purpose, core syntax and practical use of {title.lower()}. Re-run the examples, complete the practice set and pass the topic quiz before attempting the module examination.",
        'revision': [definition, why, f"Core syntax: {syntax}", f"Key concepts: {concepts}"],
    })

# Every topic receives 25 distinct task prompts, grouped by difficulty and skill.
def build_practice(module):
    tasks = module['exercises']
    groups = [
        ('Beginner', [f"{tasks[0]} Add clear comments and print the result.", f"{tasks[1]} Use only concepts introduced in this lesson.", f"{tasks[2]} Test the simplest valid input first.", f"{tasks[3]} Include one empty or boundary input.", f"{tasks[4]} Explain your solution in three sentences."]),
        ('Intermediate', [f"Extend this task: {tasks[0]} Add input validation and a reusable function.", f"Extend this task: {tasks[1]} Separate the logic from input/output.", f"Extend this task: {tasks[2]} Handle at least two edge cases.", f"Extend this task: {tasks[3]} Add a second realistic requirement.", f"Extend this task: {tasks[4]} Write tests for normal and invalid cases."]),
        ('Advanced', [f"Design a maintainable solution for: {tasks[0]} State assumptions and complexity.", f"Refactor this requirement: {tasks[1]} Use clear abstractions and test boundaries.", f"Build a robust version of: {tasks[2]} Include failure handling and useful errors.", f"Turn this into a reusable component: {tasks[3]} Document its interface.", f"Create a production-minded solution for: {tasks[4]} Discuss security, performance and maintainability."]),
        ('Output prediction', [f"Predict the output of example {i+1} in this lesson. Explain the value of each variable." for i in range(5)]),
        ('Debugging', [f"Debug example {i+1}: introduce one likely beginner mistake, identify the exception or wrong result, and correct it." for i in range(5)]),
    ]
    result=[]
    for category, prompts in groups:
        for i,prompt in enumerate(prompts):
            item = {'id':f"{module['id']}-{category.lower().replace(' ','-')}-{i+1}", 'category':category,
                    'prompt':prompt, 'hint':f"Review the '{module['examples'][i]['title']}' example and identify the input, expected result and one edge case.",
                    'solution':f"A valid solution should satisfy this requirement: {tasks[i]}. Start with a small test case, implement the core logic using {module['title'].lower()}, then test normal, boundary and invalid inputs. Compare your result with the requirement before considering the task complete."}
            if category == 'Output prediction': item['reference_code'] = module['examples'][i]['code']
            if category == 'Debugging': item['buggy_code'] = module['examples'][i]['code'] + "\nprint(missing_variable)"
            result.append(item)
    return result

for module in MODULES:
    module['practice'] = build_practice(module)
    # A 12-question topic quiz: concept checks, syntax, examples and application.
    module['quiz'] = [
        {'type':'mcq','question':f"Which statement best describes {module['title'].lower()}?",'options':[module['definition'], 'A way to style a web page', 'A hardware component', 'A command that only works in spreadsheets'],'answer':0,'explanation':module['definition']},
        {'type':'mcq','question':f"Why do developers use {module['title'].lower()}?",'options':[module['why'], 'Only to make code longer', 'To avoid testing', 'To replace every other programming concept'],'answer':0,'explanation':module['why']},
        {'type':'mcq','question':'Where is this topic used in practice?','options':[module['real_life'], 'Only in drawing applications', 'Only when a computer is offline', 'Nowhere outside a classroom'],'answer':0,'explanation':module['real_life']},
        {'type':'mcq','question':'What is the best learning approach for this topic?','options':['Run examples, predict results, then test edge cases','Memorize without running code','Skip error messages','Copy code without reading it'],'answer':0,'explanation':'Active practice and testing help you understand behavior, not just remember syntax.'},
        {'type':'mcq','question':'Which is the safest general coding habit?','options':['Validate inputs and handle expected failures','Assume every input is correct','Hide all exceptions','Use unclear variable names'],'answer':0,'explanation':'Validation and explicit error handling make programs more reliable.'},
        {'type':'true_false','question':f"{module['title']} should be learned by running and modifying examples.",'options':['True','False'],'answer':0,'explanation':'Changing examples and predicting outputs builds practical understanding.'},
        {'type':'fill','question':f"Fill in the blank: {module['title']} is best described as ______.",'options':[module['definition'], 'A way to style a web page', 'A computer hardware device', 'A command used only in spreadsheets'],'answer':0,'explanation':module['definition']},
        {'type':'output','question':f"Study this syntax: {module['syntax']} What should you do before trusting an output?",'options':['Trace the values and run a test','Assume it is always correct','Delete the code','Ignore input types'],'answer':0,'explanation':'Trace values, inspect types and run the example with test inputs.'},
        {'type':'mcq','question':'What should you do when an example fails?','options':['Read the traceback and isolate the smallest failing case','Delete the project','Ignore the error','Change many lines at once'],'answer':0,'explanation':'A traceback and a minimal reproduction help locate the cause.'},
        {'type':'debug','question':'Find the error in this snippet:','code':module['examples'][0]['code'] + "\nprint(missing_variable)",'options':['The final line uses missing_variable before it has been defined','Python cannot use print()','Every string must use triple quotes','The import statement must be last'],'answer':0,'explanation':'The final print refers to a name that has not been assigned. Define it first or print a name that already exists.'},
        {'type':'mcq','question':'Which practice improves maintainability?','options':['Use meaningful names and small focused functions','Put every operation in one giant expression','Avoid comments on complex decisions','Duplicate the same logic everywhere'],'answer':0,'explanation':'Readable structure reduces the cost of future changes.'},
        {'type':'mcq','question':'How should you check that you understand this topic?','options':['Complete practice tasks and explain the result','Only read the title','Skip the quiz','Memorize one output'],'answer':0,'explanation':'You should be able to implement, test and explain the concept.'},
    ]

