DAILY_CHALLENGES = [
 {'id':'sum-even','level':'Easy','title':'Sum the even numbers','description':'Given a list of integers, return the sum of only the even values.','input':'A list such as [1, 2, 3, 4, 6].','output':'12','constraints':'The list may be empty; values may be negative.','tests':['[1, 2, 3, 4, 6] → 12','[] → 0','[-2, 3, 8] → 6'],'hint':'Use a running total and the remainder operator % to test evenness.','solution':"def sum_even(values):\n    total = 0\n    for value in values:\n        if value % 2 == 0:\n            total += value\n    return total\nprint(sum_even([1, 2, 3, 4, 6]))",'explanation':'The loop visits each value once, checks whether it is divisible by two and adds only even values. Time complexity is O(n).'},
 {'id':'word-frequency','level':'Medium','title':'Word frequency counter','description':'Count how many times each word appears, ignoring case and surrounding punctuation.','input':'A sentence such as "Code, code well!".','output':"{'code': 2, 'well': 1}",'constraints':'Ignore case; punctuation at word boundaries should not create separate words.','tests':['"Code, code well!" → code:2, well:1','"Python python" → python:2','"" → {}'],'hint':'Normalize case, extract word tokens and update a dictionary count.','solution':"import re\ndef word_frequency(text):\n    counts = {}\n    for word in re.findall(r'[a-zA-Z]+', text.lower()):\n        counts[word] = counts.get(word, 0) + 1\n    return counts\nprint(word_frequency('Code, code well!'))",'explanation':'The regular expression extracts alphabetic tokens; the dictionary stores each token count. For multilingual text, use a Unicode-aware tokenization strategy.'},
 {'id':'merge-intervals','level':'Hard','title':'Merge overlapping intervals','description':'Given intervals sorted by start or in arbitrary order, merge all overlapping ranges.','input':'[[1,3], [2,6], [8,10], [9,12]].','output':'[[1,6], [8,12]].','constraints':'Intervals have start <= end; touching intervals may be treated as overlapping only if you choose and document that rule.','tests':['[[1,3],[2,6],[8,10],[9,12]] → [[1,6],[8,12]]','[[1,2]] → [[1,2]]','[] → []'],'hint':'Sort by start. Compare each interval with the last interval in the result.','solution':"def merge_intervals(intervals):\n    if not intervals: return []\n    intervals = sorted(intervals)\n    merged = [list(intervals[0])]\n    for start, end in intervals[1:]:\n        if start <= merged[-1][1]:\n            merged[-1][1] = max(merged[-1][1], end)\n        else:\n            merged.append([start, end])\n    return merged\nprint(merge_intervals([[1,3],[2,6],[8,10],[9,12]]))",'explanation':'Sorting costs O(n log n); the merge pass is O(n). The algorithm stores only the merged output.'},
]

# Expected outputs and line-by-line walkthroughs are kept separately from the
# core lesson catalogue so the course content remains easy to review and extend.
from pathlib import Path as _CoursePath
import json as _course_json
_details_path = _CoursePath(__file__).with_name('example_details.json')
if _details_path.exists():
    _example_details = _course_json.loads(_details_path.read_text(encoding='utf-8'))
    for _module in MODULES:
        for _index, _example in enumerate(_module['examples']):
            _example.update(_example_details[str(_module['id'])][_index])
